      "path": "package.json",
      "content": "{\n  \"name\": \"@roarpeng/graphflow\",\n  \"version\": \"3.9.2\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"files\": [\n    \"dist\",\n    \"assets\",\n    \"skills\",\n    \"mcp.json\",\n    \"README.md\",\n    \"LICENSE\",\n    \"README.zh.md\",\n    \"VSIX-INSTALL.md\"\n  ],\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"description\": \"Token-First Surgical Code Engine for AI Coding Agents (true AST for TS/JS via @babel/parser and for Python/Go/Rust/C/C++/C# via optional tree-sitter grammars, receiver-aware Blast-Radius Guard, Output Dehydrator, Habit & Git Co-Change Macros)\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"default\": \"./dist/index.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"bin\": {\n    \"graphflow\": \"dist/cli.js\",\n    \"graphflow-mcp\": \"dist/mcp-server.js\"\n  },\n  \"scripts\": {\n    \"prepublishOnly\": \"npm run build\",\n    \"build\": \"tsc -p tsconfig.json\",\n    \"start\": \"tsx src/cli.ts\",\n    \"start:mcp\": \"tsx src/mcp-server.ts\",\n    \"test\": \"tsx tests/run-all.ts\",\n    \"bench\": \"node scripts/benchmark.mjs\",\n    \"preflight\": \"node scripts/release-preflight.mjs\",\n    \"preflight:release\": \"node scripts/release-preflight.mjs --with-tests --with-package\",\n    \"verify:parsers\": \"node scripts/verify-parsers.mjs\",\n    \"verify:parsers:strict\": \"node scripts/verify-parsers.mjs --strict\",\n    \"task\": \"tsx src/cli.ts task\",\n    \"reflect\": \"tsx src/cli.ts reflect\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Roarpeng/GraphFlow\"\n  },\n  \"author\": \"Roarpeng\",\n  \"license\": \"Apache-2.0\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Roarpeng/GraphFlow/issues\"\n  },\n  \"homepage\": \"https://github.com/Roarpeng/GraphFlow#readme\",\n  \"dependencies\": {\n    \"@babel/parser\": \"^7.26.0\",\n    \"@modelcontextprotocol/sdk\": \"^1.32.1\",\n    \"tree-sitter\": \"0.22.4\"\n  },\n  \"optionalDependencies\": {\n    \"tree-sitter-c\": \"0.23.6\",\n    \"tree-sitter-c-sharp\": \"0.23.1\",\n    \"tree-sitter-cpp\": \"0.23.4\",\n    \"tree-sitter-go\": \"0.23.4\",\n    \"tree-sitter-python\": \"0.23.6\",\n    \"tree-sitter-rust\": \"0.24.0\"\n  },\n  \"overrides\": {\n    \"tree-sitter\": \"0.22.4\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.10.2\",\n    \"tsx\": \"^4.19.2\",\n    \"typescript\": \"^5.7.2\"\n  }\n}\n"
